process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const TOK=process.env.GH_TOKEN||''; const REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const WP=process.env.WP_URL||'https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from(process.env.WP_USER+':'+process.env.WP_APP_PASS).toString('base64');
const B64='' ; const VER='FBTE1G';
const out={v:VER,zingsniai:[]}; const miegok=ms=>new Promise(r=>setTimeout(r,ms));
async function put(path,buf,msg){ const u='https://api.github.com/repos/'+REPO+'/contents/'+path; const h={Authorization:'Bearer '+TOK,'Content-Type':'application/json'};
  let sha=null; try{const g=await fetch(u,{headers:h}); if(g.ok){sha=(await g.json()).sha;}}catch(e){}
  const b={message:msg,content:buf.toString('base64')}; if(sha)b.sha=sha; return (await fetch(u,{method:'PUT',headers:h,body:JSON.stringify(b)})).status; }
const A={Authorization:AUTH,'Content-Type':'application/json'}; const SNIP=WP+'/wp-json/code-snippets/v1/snippets';
async function fx(u,o,k){ for(let i=0;i<6;i++){ try{ return await fetch(u,o); }catch(e){ await miegok(10000); } } throw new Error('fx:'+k); }
let sid=null;
try{
  const l=await fx(SNIP,{headers:A},'list'); const arr=JSON.parse(await l.text());
  const temp=(Array.isArray(arr)?arr:[]).filter(s=>s.active&&/^TEMP/.test(s.name||''));
  for(const s of temp){ await fetch(SNIP+'/'+s.id,{method:'POST',headers:A,body:JSON.stringify({id:s.id,active:false})}); }
  const c=await fx(SNIP,{method:'POST',headers:A,body:JSON.stringify({name:'TEMP FBT Deploy v163',code:Buffer.from(B64,'base64').toString('utf8'),scope:'global',active:true,priority:5})},'create');
  const cr=JSON.parse(await c.text()); sid=cr.id;
  await miegok(9000);
  const r=await fx(WP+'/?ps_fbtdep7=GO',{headers:{'Cache-Control':'no-cache'}},'dep');
  try{ out.deploy=JSON.parse(await r.text()); }catch(e){ out.deploy_zalias=(await r.text()).slice(0,800); }
}catch(e){ out.klaida=String(e).slice(0,400); }
try{ if(sid) await fetch(SNIP+'/'+sid,{method:'POST',headers:A,body:JSON.stringify({id:sid,active:false})}); }catch(e){}
try{
  const ck = out.deploy && out.deploy.cookies ? out.deploy.cookies : null;
  if(ck){
    const pw = await import('playwright');
    const br = await pw.chromium.launch();
    const ctx = await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1360,height:900}});
    await ctx.addCookies(ck.map(c=>({name:c[0],value:c[1],domain:'dev.avesa.lt',path:'/'})));
    const pg = await ctx.newPage();
    await pg.goto(WP+'/wp-admin/admin.php?page=petshop-fbt',{waitUntil:'domcontentloaded',timeout:45000});
    await pg.waitForTimeout(4000);
    out.zingsniai.push('puslapis_h1:'+await pg.locator('h1:has-text("Dažnai perkama kartu")').count());
    out.zingsniai.push('meniu_punktas:'+await pg.locator('#adminmenu a:has-text("Perkame kartu")').count());
    out.zingsniai.push('po_petshop_prekes:'+await pg.locator('#adminmenu li:has(a:has-text("Petshop prekės")) a:has-text("Perkame kartu")').count());
    const s1=await pg.screenshot({fullPage:false});
    await put('screenshots/fbt_menu_v163.png', s1, VER);
    await br.close();
  }
}catch(e){ out.pw_klaida=String(e).slice(0,400); }
if(out.deploy) delete out.deploy.cookies;
await put('deploy/fbte1g.json', Buffer.from(JSON.stringify(out,null,1)), VER);
